def solve(albedo1=0.4, solar_irradiance=1370.0, albedo2=0.6):
    sigma = 5.670374419e-8  # Stefan-Boltzmann constant, W m^-2 K^-4

    # Effective temperature: (1-a)*S/4 = sigma*T^4
    T1 = ((1 - albedo1) * solar_irradiance / (4 * sigma)) ** 0.25
    T2 = ((1 - albedo2) * solar_irradiance / (4 * sigma)) ** 0.25

    return {
        "1": {"value": T1, "unit": "K"},
        "2": {"value": T2, "unit": "K"},
    }
